insert into public.receta_pasos values ('26c86579-9507-5431-b6b8-e0d9481b1f06', 1, 'Hacé un puré con la banana.') on conflict do nothing;
insert into public.receta_pasos values ('26c86579-9507-5431-b6b8-e0d9481b1f06', 2, 'Agregá la avena, la miel y el aceite, y mezclá hasta que se forme una pasta húmeda. Si querés, sumá canela y chips o pasas.') on conflict do nothing;
insert into public.receta_pasos values ('26c86579-9507-5431-b6b8-e0d9481b1f06', 3, 'Armá bolitas, aplastalas un poco y ponelas sobre papel manteca en la canasta.') on conflict do nothing;
insert into public.receta_pasos values ('26c86579-9507-5431-b6b8-e0d9481b1f06', 4, 'Cociná unos 10 minutos a 160 °C, hasta que se doren los bordes.') on conflict do nothing;
